// OWN-030 lane "emit": the SAME node tree the graph lane built (own-029 `r<k>/tree.json`), transpiled mechanically
// to one HTML file. No NodeGX runtime, validator or render findings: what is left is the question tree and the style
// vocabulary. It writes what the parameters say and nothing else (no added shadow, spacing or hover), with:
//   - the project's token sheet, generated by the editor's own ProjectTokenCss (bundled as tokens-css.mjs);
//   - the project's noodl_modules stylesheets (the preset's font, the Lucide icon font), as the runtime loads them;
//   - the body defaults the runtime page has: margin 0, the sans font, the foreground colour on the background.
//
//   node emit.mjs <tree.json> <graph project dir> <out dir> [--raw]
// --raw (OWN-030 §7 emit-raw): no token sheet; every var(--x) falls back to the browser default.
import fs from 'node:fs';
import path from 'node:path';
import { generateProjectTokenCss } from './tokens-css.mjs';

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const dim = (v) => (v == null ? undefined : typeof v === 'object' ? `${v.value}${v.unit || 'px'}` : typeof v === 'number' ? `${v}px` : String(v));
const kebab = (k) => k.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
// parameters that are CSS as they stand (dimension objects become "Npx")
const PLAIN = ['flexDirection', 'flexWrap', 'alignItems', 'justifyContent', 'rowGap', 'columnGap', 'paddingTop', 'paddingBottom', 'paddingLeft', 'paddingRight',
  'marginTop', 'marginBottom', 'marginLeft', 'marginRight', 'maxWidth', 'minWidth', 'minHeight', 'maxHeight', 'backgroundColor', 'backgroundSize', 'backgroundPosition',
  'borderRadius', 'borderStyle', 'borderWidth', 'borderColor', 'borderTopStyle', 'borderTopWidth', 'borderTopColor', 'borderBottomStyle', 'borderBottomWidth', 'borderBottomColor',
  'boxShadow', 'opacity', 'color', 'fontSize', 'fontWeight', 'fontFamily', 'lineHeight', 'letterSpacing', 'textTransform', 'objectFit', 'aspectRatio'];

function css(n) {
  const p = n.params || {}, out = {};
  for (const k of PLAIN) if (p[k] !== undefined) out[kebab(k)] = dim(p[k]);
  if (p.textAlignX) out['text-align'] = p.textAlignX;
  if (p.clip) out.overflow = 'hidden';
  // a ground: the gradient is drawn over the picture, in one background-image (the runtime composes them the same way)
  const layers = [p.backgroundGradient, p.backgroundImage && `url("${p.backgroundImage}")`].filter(Boolean);
  if (layers.length) out['background-image'] = layers.join(', ');
  // sizeMode: contentHeight = the width it is given, the height of its content; contentSize = both from content;
  // explicit = both as set. Unset: the runtime's default box is the full width.
  const sm = p.sizeMode;
  if (sm === 'contentSize') { out.width = dim(p.width) || 'fit-content'; out.height = 'auto'; }
  else if (sm === 'explicit') { out.width = dim(p.width) || '100%'; if (p.height) out.height = dim(p.height); }
  else { out.width = dim(p.width) || (n.type === 'net.noodl.controls.button' ? 'fit-content' : '100%'); if (p.height) out.height = dim(p.height); }
  out['box-sizing'] = 'border-box';
  return out;
}
const style = (o) => Object.entries(o).filter(([, v]) => v !== undefined).map(([k, v]) => `${k}:${v}`).join(';');

export function emitPage(tree, { tokens = '', moduleCss = [], title = '' } = {}) {
  const rules = [];
  let k = 0;
  const render = (nodes, i) => {
    const n = nodes[i], kids = nodes.map((m, j) => (m.parent === i ? j : -1)).filter((j) => j >= 0);
    const inner = () => kids.map((j) => render(nodes, j)).join('');
    const p = n.params || {};
    switch (n.type) {
      case 'Group': {
        const tag = ['header', 'section', 'footer', 'nav', 'main', 'article', 'aside'].includes(p.as) ? p.as : 'div';
        return `<${tag} style="${esc(style({ display: 'flex', 'flex-direction': p.flexDirection || 'column', ...css(n) }))}">${inner()}</${tag}>`;
      }
      case 'net.noodl.visual.columns': {
        const cls = `c${++k}`, gap = dim(p.marginX) || '0px';
        const cols = (s) => s.trim().split(/\s+/).map((x) => `${Number(x) || 1}fr`).join(' ');
        const tpl = p.sizing === 'autoFit' ? `repeat(auto-fit, minmax(${dim(p.minWidth) || '240px'}, 1fr))` : cols(p.layoutString || '1');
        rules.push(`.${cls}{display:grid;grid-template-columns:${tpl};gap:${gap};width:100%}`);
        if (p.sizing !== 'autoFit') {
          if (p.mediumBreakpoint && p.mediumLayout) rules.push(`@media (max-width:${dim(p.mediumBreakpoint)}){.${cls}{grid-template-columns:${cols(p.mediumLayout)}}}`);
          if (p.smallBreakpoint && p.smallLayout) rules.push(`@media (max-width:${dim(p.smallBreakpoint)}){.${cls}{grid-template-columns:${cols(p.smallLayout)}}}`);
        }
        return `<div class="${cls}">${kids.map((j) => `<div style="min-width:0;display:flex;flex-direction:column">${render(nodes, j)}</div>`).join('')}</div>`;
      }
      case 'Text': {
        const tag = /^h[1-6]$|^p$|^span$/.test(p.as || '') ? p.as : 'p';
        const o = css(n); if (p.sizeMode === 'contentSize') o.width = 'auto';
        return `<${tag} style="${esc(style({ margin: '0', ...o }))}">${esc(p.text)}</${tag}>`;
      }
      case 'net.noodl.controls.button':
        return `<button type="button" style="${esc(style({ 'font-family': 'inherit', cursor: 'pointer', ...css(n) }))}">${esc(p.label)}</button>`;
      case 'Image':
        return `<img src="${esc(p.src)}" alt="${esc(p.alt)}" style="${esc(style({ display: 'block', ...css(n) }))}">`;
      case 'net.noodl.visual.icon': {
        const src = p.iconIconSource || {};
        return `<i class="${esc(`${src.class || ''} ${src.code || ''}`.trim())}" aria-hidden="true" style="${esc(style({ 'font-size': dim(p.iconSize ?? 24), color: p.iconColor, 'line-height': '1', 'font-style': 'normal' }))}"></i>`;
      }
      case 'net.noodl.controls.textinput':
        return `<input type="${esc(p.type || 'text')}" placeholder="${esc(p.placeholder || '')}" style="${esc(style({ 'font-family': 'inherit', ...css(n) }))}">`;
      default:
        return `<div>${inner()}</div>`;
    }
  };
  const body = tree.sections.map((s) => render(s.nodes, s.nodes.findIndex((n) => n.parent === -1))).join('\n');
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title>
${moduleCss.map((h) => `<link rel="stylesheet" href="${esc(h)}">`).join('\n')}
<style>${tokens}
body{margin:0;font-family:var(--font-sans);color:var(--foreground);background:var(--background)}
${rules.join('\n')}</style></head>
<body><main style="display:flex;flex-direction:column">
${body}
</main></body></html>`;
}

// the stylesheets each noodl_modules package declares for the browser (manifest.browser.stylesheets)
export function moduleStylesheets(projectDir) {
  const dir = path.join(projectDir, 'noodl_modules');
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir).flatMap((m) => { try { return JSON.parse(fs.readFileSync(path.join(dir, m, 'manifest.json'), 'utf8')).browser?.stylesheets || []; } catch { return []; } });
}

export function projectTokenCss(projectDir) {
  const pj = JSON.parse(fs.readFileSync(path.join(projectDir, 'nodegx.project.json'), 'utf8'));
  return generateProjectTokenCss({ getMetaData: (key) => pj.metadata?.[key] });
}

// write <out>/index.html beside a copy of the project's noodl_modules, so the page's relative paths resolve
export function emitSite(treeFile, projectDir, outDir, { raw = false } = {}) {
  const tree = JSON.parse(fs.readFileSync(treeFile, 'utf8'));
  fs.mkdirSync(outDir, { recursive: true });
  fs.cpSync(path.join(projectDir, 'noodl_modules'), path.join(outDir, 'noodl_modules'), { recursive: true });
  const html = emitPage(tree, { tokens: raw ? '' : projectTokenCss(projectDir), moduleCss: moduleStylesheets(projectDir), title: tree.card?.name || '' });
  fs.writeFileSync(path.join(outDir, 'index.html'), html);
  return path.join(outDir, 'index.html');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const [tree, project, out] = process.argv.slice(2);
  console.log(emitSite(tree, project, out, { raw: process.argv.includes('--raw') }));
}
